  pub(crate) fn analyze(
    asts: &'run HashMap<PathBuf, Ast<'src>>,
    config: &Config,
    doc: Option<String>,
    groups: &[StringLiteral<'src>],
    loaded: &[PathBuf],
    name: Option<Name<'src>>,
    overrides: &mut HashMap<Number, String>,
    paths: &HashMap<PathBuf, PathBuf>,
    private: bool,
    root: &Path,
  ) -> RunResult<'src, Justfile<'src>> {
    Self::default().justfile(
      asts, config, doc, groups, loaded, name, overrides, paths, private, root,
    )
  }

  fn justfile(
    mut self,
    asts: &'run HashMap<PathBuf, Ast<'src>>,
    config: &Config,
    doc: Option<String>,
    groups: &[StringLiteral<'src>],
    loaded: &[PathBuf],
    name: Option<Name<'src>>,
    overrides: &mut HashMap<Number, String>,
    paths: &HashMap<PathBuf, PathBuf>,
    private: bool,
    root: &Path,
  ) -> RunResult<'src, Justfile<'src>> {
    let mut definitions = HashMap::new();
    let mut imports = HashSet::new();
    let mut unstable_features = BTreeSet::new();

    let mut stack = Vec::new();
    let ast = asts.get(root).unwrap();
    stack.push(ast);

    while let Some(ast) = stack.pop() {
      unstable_features.extend(&ast.unstable_features);

      for item in &ast.items {
        match item {
          Item::Alias(alias) => {
            Self::define(&mut definitions, alias.name, "alias", false)?;
            self.aliases.insert(alias.clone());
          }
          Item::Assignment(assignment) => {
            self.assignments.push(assignment);
          }
          Item::Comment(_) => (),
          Item::Function(function) => {
            self.functions.push(function);
          }
          Item::Import { absolute, .. } => {
            if let Some(absolute) = absolute {
              if imports.insert(absolute) {
                stack.push(asts.get(absolute).unwrap());
              }
            }
          }
          Item::Module {
            absolute,
            doc,
            groups,
            name,
            private,
            ..
          } => {
            if let Some(absolute) = absolute {
              Self::define(&mut definitions, *name, "module", false)?;
              self.modules.insert(Self::analyze(
                asts,
                config,
                doc.clone(),
                groups.as_slice(),
                loaded,
                Some(*name),
                overrides,
                paths,
                *private,
                absolute,
              )?);
            }
          }
          Item::Newline => {}
          Item::Recipe(recipe) => {
            if recipe.enabled() {
              Self::analyze_recipe(recipe)?;
              self.recipes.push(recipe);
            }
          }
          Item::Set(set) => {
            self.analyze_set(set)?;
            self.sets.insert(set.clone());
