          overrides.insert(assignment.number, value.clone());
        } else {
          unknown_overrides.push(path.join(name));
        }
      } else if path.starts_with(&ast.module_path)
        && !self
          .modules
          .contains_key(&path.components[ast.module_path.components.len()])
