      loaded: loaded.into(),
      module_path: ast.module_path.clone(),
      modules: self.modules,
      name,
      private,
      recipes,
      settings,
      source,
      unexports: self.unexports,
      unstable_features,
      warnings: self.warnings,
      working_directory: ast.working_directory.clone(),
